CREATE TABLE auth_owner (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  name TEXT NOT NULL,
  installation_id TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  password_changed_at TEXT NOT NULL
);
CREATE TABLE auth_sessions (
  id TEXT PRIMARY KEY,
  digest TEXT NOT NULL UNIQUE,
  device_label TEXT NOT NULL,
  created_at TEXT NOT NULL,
  last_used_at TEXT NOT NULL,
  expires_at TEXT NOT NULL
);
CREATE TABLE auth_access_tokens (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
  digest TEXT NOT NULL UNIQUE,
  prefix TEXT NOT NULL,
  scope TEXT NOT NULL CHECK (scope = 'read'),
  created_at TEXT NOT NULL,
  last_used_at TEXT
);
CREATE TABLE workspace_projects (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  version INTEGER NOT NULL CHECK (version > 0),
  archived_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, color TEXT NOT NULL DEFAULT 'gray' CHECK (color IN ('violet', 'ochre', 'gray', 'green')), position INTEGER NOT NULL DEFAULT 0 CHECK (position >= 0));
INSERT INTO workspace_projects VALUES('251e7972-0018-4751-ba21-505fa8a2226b','Tinyfold',1,NULL,'2026-10-25T12:56:34.063Z','2026-10-25T12:56:34.063Z','violet',0);
