INSERT INTO workspace_projects VALUES('96215133-643c-4dbb-92d8-c395bad741d1','Site pessoal 2024',2,'2026-10-30T20:26:34.063Z','2026-10-25T17:26:34.063Z','2026-10-30T20:26:34.063Z','green',3);
CREATE TABLE workspace_documents (
  id TEXT PRIMARY KEY,
  project_id TEXT REFERENCES workspace_projects(id) ON DELETE SET NULL,
  title TEXT NOT NULL,
  content TEXT NOT NULL CHECK (json_valid(content)),
  plain_text TEXT NOT NULL,
  search_text TEXT NOT NULL,
  format_version INTEGER NOT NULL CHECK (format_version = 1),
  version INTEGER NOT NULL CHECK (version > 0),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT
, pinned_at TEXT, folder_id TEXT REFERENCES workspace_folders(id));
