INSERT INTO workspace_documents VALUES('ac77421c-a393-4347-aa2a-44d7687a4771','48ca9d43-eb1e-4b69-9fde-bce445bd3034','Lista de compras','[{"id":"1668e735-2444-4ba9-8668-0befb2167e26","type":"checkListItem","props":{"checked":true},"content":[{"type":"text","text":"Tinta acrílica fosca, 18 litros","styles":{}}]},{"id":"2dc9299a-cd92-459d-8c2f-a70db8118f38","type":"checkListItem","props":{"checked":false},"content":[{"type":"text","text":"Fita crepe e lona","styles":{}}]},{"id":"ec71bf16-c58f-409d-9051-c0695d718754","type":"checkListItem","props":{"checked":false},"content":[{"type":"text","text":"Luminária de mesa","styles":{}}]}]',unistr('Tinta acrílica fosca, 18 litros\u000aFita crepe e lona\u000aLuminária de mesa'),unistr('lista de compras\u000atinta acrilica fosca, 18 litros\u000afita crepe e lona\u000aluminaria de mesa'),1,1,'2026-10-29T11:26:34.063Z','2026-10-29T11:26:34.063Z',NULL,NULL,'a1b30ccb-fe8a-45b0-868a-0c4d3baf6507');
INSERT INTO workspace_documents VALUES('c4239185-0e46-487d-b1da-200a53271dd0','251e7972-0018-4751-ba21-505fa8a2226b','MCP somente leitura','[{"id":"c68fc8d6-804d-4d51-a476-76833789547d","type":"paragraph","content":[{"type":"text","text":"O Claude Code consulta documentos, desenhos e tarefas por MCP, sem escrever nada.","styles":{}}]},{"id":"737c19ec-dbf5-43a8-8432-0809dc45d24c","type":"paragraph","content":[{"type":"text","text":"Gerar token pessoal no Perfil, mostrado uma única vez, com o comando pronto para copiar.","styles":{}}]},{"id":"875138e7-1c01-4bf0-8436-4225f82715df","type":"paragraph","content":[{"type":"text","text":"Cada resposta cabe em 45.000 caracteres; documentos longos vêm em páginas.","styles":{}}]}]',unistr('O Claude Code consulta documentos, desenhos e tarefas por MCP, sem escrever nada.\u000aGerar token pessoal no Perfil, mostrado uma única vez, com o comando pronto para copiar.\u000aCada resposta cabe em 45.000 caracteres; documentos longos vêm em páginas.'),unistr('mcp somente leitura\u000ao claude code consulta documentos, desenhos e tarefas por mcp, sem escrever nada.\u000agerar token pessoal no perfil, mostrado uma unica vez, com o comando pronto para copiar.\u000acada resposta cabe em 45.000 caracteres; documentos longos vem em paginas.'),1,1,'2026-10-29T20:26:34.063Z','2026-10-29T20:26:34.063Z',NULL,NULL,'401c4059-6141-4e52-96e1-49c07e7d5bd5');
INSERT INTO workspace_documents VALUES('34a03860-578f-499c-b233-1794f51c0780','251e7972-0018-4751-ba21-505fa8a2226b','Notas de arquitetura','[{"id":"70a9297d-e33f-4110-8442-88e329929721","type":"heading","props":{"level":2},"content":[{"type":"text","text":"Módulos","styles":{}}]},{"id":"cba0682b-bebe-444f-8879-441ce3a730b3","type":"paragraph","content":[{"type":"text","text":"core, auth, workspace, server e web, cada um com domínio, aplicação e infraestrutura.","styles":{}}]},{"id":"079353ce-00c9-4773-b69c-880f75462d39","type":"heading","props":{"level":2},"content":[{"type":"text","text":"Persistência","styles":{}}]},{"id":"8217cf84-ff41-4584-85ab-c6c508de3153","type":"paragraph","content":[{"type":"text","text":"SQLite no servidor, com migrações numeradas e escritas idempotentes.","styles":{}}]}]',unistr('Módulos\u000acore, auth, workspace, server e web, cada um com domínio, aplicação e infraestrutura.\u000aPersistência\u000aSQLite no servidor, com migrações numeradas e escritas idempotentes.'),unistr('notas de arquitetura\u000amodulos\u000acore, auth, workspace, server e web, cada um com dominio, aplicacao e infraestrutura.\u000apersistencia\u000asqlite no servidor, com migracoes numeradas e escritas idempotentes.'),1,1,'2026-10-29T21:56:34.063Z','2026-10-29T21:56:34.063Z',NULL,NULL,'fbfcde27-03ac-4dee-b7c8-63e2d3ff9542');
INSERT INTO workspace_documents VALUES('911a7c67-3486-4638-9291-986ee7f64151','251e7972-0018-4751-ba21-505fa8a2226b','Visão do produto','[{"id":"67ac3b3b-662b-4355-89bb-9005bf72fba3","type":"heading","props":{"level":1},"content":[{"type":"text","text":"Por que existe","styles":{}}]},{"id":"c0cb8f1e-b278-422e-98b1-c61644dce66b","type":"paragraph","content":[{"type":"text","text":"Um espaço pessoal e minimalista para conduzir projetos, com escrita, desenho e tarefas no mesmo lugar, sem o excesso de Notion, Excalidraw e Trello.","styles":{}}]},{"id":"4c7cb63b-e002-4154-ba9f-4106b2ab681f","type":"heading","props":{"level":2},"content":[{"type":"text","text":"Princípios","styles":{}}]},{"id":"86bfab1b-be59-4551-b559-3b973731b3bd","type":"bulletListItem","content":[{"type":"text","text":"O projeto é o centro.","styles":{}}]},{"id":"e98a33bf-2bf7-423e-a320-585eadc72455","type":"bulletListItem","content":[{"type":"text","text":"Cada ferramenta faz menos que a original.","styles":{}}]},{"id":"63ef53ad-891b-4326-83d3-415afa6115e8","type":"bulletListItem","content":[{"type":"text","text":"Ligações vivem nos documentos.","styles":{}}]},{"id":"2d6fe786-f10a-4380-9167-7917d58a9128","type":"bulletListItem","content":[{"type":"text","text":"Nada se perde.","styles":{}}]},{"id":"5d6090f3-9d8b-475e-a20b-fc81a4ab486c","type":"paragraph","content":[{"type":"text","text":"Próximo passo: gerar token pessoal no Perfil para o Claude Code ler o Tinyfold.","styles":{}}]}]',unistr('Por que existe\u000aUm espaço pessoal e minimalista para conduzir projetos, com escrita, desenho e tarefas no mesmo lugar, sem o excesso de Notion, Excalidraw e Trello.\u000aPrincípios\u000aO projeto é o centro.\u000aCada ferramenta faz menos que a original.\u000aLigações vivem nos documentos.\u000aNada se perde.\u000aPróximo passo: gerar token pessoal no Perfil para o Claude Code ler o Tinyfold.'),unistr('visao do produto\u000apor que existe\u000aum espaco pessoal e minimalista para conduzir projetos, com escrita, desenho e tarefas no mesmo lugar, sem o excesso de notion, excalidraw e trello.\u000aprincipios\u000ao projeto e o centro.\u000acada ferramenta faz menos que a original.\u000aligacoes vivem nos documentos.\u000anada se perde.\u000aproximo passo: gerar token pessoal no perfil para o claude code ler o tinyfold.'),1,1,'2026-10-30T14:26:34.063Z','2026-10-30T14:26:34.063Z',NULL,'2026-10-30T15:56:34.063Z',NULL);
INSERT INTO workspace_documents VALUES('405974d2-db3b-498b-aaa5-a03a4a93d1d6','96215133-643c-4dbb-92d8-c395bad741d1','Portfólio','[{"id":"eb9cc564-ab11-4972-8849-4530d7fb9444","type":"paragraph","content":[{"type":"text","text":"Projetos de 2024 e um texto curto de apresentação.","styles":{}}]}]','Projetos de 2024 e um texto curto de apresentação.',unistr('portfolio\u000aprojetos de 2024 e um texto curto de apresentacao.'),1,1,'2026-10-30T18:56:34.063Z','2026-10-30T18:56:34.063Z',NULL,NULL,NULL);
